solution.solution.js:
async function getJSON(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  return response.json();
}

async function activeByTeam(url) {
  const users = await getJSON(url);
  const teams = {};
  for (const { name, team, active } of users) {
    if (!teams[team]) teams[team] = [];
    if (active) teams[team].push(name);
  }
  for (const names of Object.values(teams)) names.sort();
  return teams;
}

function searchUrl(base, params) {
  const kept = Object.entries(params).filter(([key, value]) => value !== null && value !== undefined && value !== "");
  const query = String(new URLSearchParams(Object.fromEntries(kept)));
  return query ? `${base}?${query}` : base;
}

unitTests:
test("getJSON reads the file", async () => {
  const users = await getJSON("users.json");
  checkEq(users.length, 5);
  checkEq(users[2].name, "Ada");
});

test("getJSON checks the status", async () => {
  try {
    await getJSON("missing.json");
    check(false, "should throw for a 404");
  } catch (e) {
    checkEq(e.message, "missing.json: HTTP 404");
  }
});

test("active users by team", async () => {
  checkEq(await activeByTeam("users.json"), { red: ["Ada", "Grace"], blue: ["Barbara"], green: [] });
});

test("search URLs", () => {
  checkEq(searchUrl("/search", { q: "tea & cake", page: 2, sort: null }), "/search?q=tea+%26+cake&page=2");
  checkEq(searchUrl("/s", { a: "", b: undefined }), "/s");
  checkEq(searchUrl("/s", { n: 0, ok: false }), "/s?n=0&ok=false");
});

